import{_ as t,o as e,c as r,a0 as a}from"./chunks/framework.Bmhw_dvp.js";const c=JSON.parse('{"title":"Troubleshooting: Studio & UI","description":"Fix UI glitches, layout overlapping, and workflow stepper issues.","frontmatter":{"title":"Troubleshooting: Studio & UI","description":"Fix UI glitches, layout overlapping, and workflow stepper issues."},"headers":[],"relativePath":"support/troubleshooting_studio.md","filePath":"support/troubleshooting_studio.md"}'),s={name:"support/troubleshooting_studio.md"};function i(n,o,l,u,p,d){return e(),r("div",null,[...o[0]||(o[0]=[a('<h1 id="troubleshooting-studio-ui" tabindex="-1">Troubleshooting: Studio &amp; UI <a class="header-anchor" href="#troubleshooting-studio-ui" aria-label="Permalink to &quot;Troubleshooting: Studio &amp; UI&quot;">​</a></h1><h2 id="_1-layout-overlapping-on-mobile" tabindex="-1">1. Layout Overlapping on Mobile <a class="header-anchor" href="#_1-layout-overlapping-on-mobile" aria-label="Permalink to &quot;1. Layout Overlapping on Mobile&quot;">​</a></h2><p><strong>Symptom:</strong> The Script Panel overlaps the Visual Stage on small screens. <strong>Cause:</strong> You may have forced &quot;Split View&quot; on a screen that is too small to accommodate it side-by-side. <strong>Solution:</strong></p><ul><li>Rotate your device to Landscape mode.</li><li>Or, switch back to <strong>Tabbed View</strong> using the layout toggle in the Studio Toolbar.</li></ul><h2 id="_2-workflow-stepper-stuck" tabindex="-1">2. Workflow Stepper Stuck <a class="header-anchor" href="#_2-workflow-stepper-stuck" aria-label="Permalink to &quot;2. Workflow Stepper Stuck&quot;">​</a></h2><p><strong>Symptom:</strong> The automation pipeline pauses and the &quot;Next Action&quot; button vanishes. <strong>Cause:</strong> You have hit a Human-in-the-Loop approval gate (e.g., waiting for you to approve the generated images). <strong>Solution:</strong> Look for a glowing &quot;Approve&quot; button. The orchestrator will not proceed to video stitching until you explicitly approve the outputs of the previous stage.</p><h2 id="_3-keyboard-shortcuts-not-working" tabindex="-1">3. Keyboard Shortcuts Not Working <a class="header-anchor" href="#_3-keyboard-shortcuts-not-working" aria-label="Permalink to &quot;3. Keyboard Shortcuts Not Working&quot;">​</a></h2><p><strong>Symptom:</strong> Pressing Spacebar to play the timeline doesn&#39;t work. <strong>Cause:</strong> Your cursor is likely focused inside a text input field (like the scene editor or prompt box). <strong>Solution:</strong> Click anywhere on the empty background of the Studio to remove focus from the text fields, then try the shortcut again.</p><h2 id="_4-ui-doesn-t-reflect-backend-state" tabindex="-1">4. UI Doesn&#39;t Reflect Backend State <a class="header-anchor" href="#_4-ui-doesn-t-reflect-backend-state" aria-label="Permalink to &quot;4. UI Doesn&#39;t Reflect Backend State&quot;">​</a></h2><p><strong>Symptom:</strong> Another user cloned your script, but you don&#39;t see it in the Project View. <strong>Cause:</strong> The frontend relies on real-time Firestore listeners, which can occasionally disconnect if your network drops. <strong>Solution:</strong> Hard refresh the browser (<code>Ctrl/Cmd + Shift + R</code>). Browser refreshes are fully supported and will now persist your active project and script state via the URL so you won&#39;t lose your place.</p>',10)])])}const g=t(s,[["render",i]]);export{c as __pageData,g as default};
